import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class WebAppSessionStartResultsSchema(pydantic.BaseModel):
    aimsid: str


class WebAppSessionStartResponseSchema(BaseRapiResponseSchema):
    results: WebAppSessionStartResultsSchema


class Session(pydantic.BaseModel):
    os: str
    client: str
    location: str
    ip: str
    startedTime: int
    hash: str
    current: bool


class SessionsListResultsSchema(pydantic.BaseModel):
    sessions: list[Session]


class SessionsListResponseSchema(BaseRapiResponseSchema):
    results: SessionsListResultsSchema


class SessionResetResponseSchema(BaseRapiResponseSchema): ...


class SessionResetAllResponseSchema(BaseRapiResponseSchema): ...
